// LinkedIn job id: search/collections URLs (?currentJobId=) or /jobs/view/<slug>-<id>
const chat = String($('When chat message received').item.json.chatInput || '');
const jobMatch = chat.match(/[?&]currentJobId=(\d+)/i) || chat.match(/\/jobs\/view\/(?:[^\/]*-)?(\d+)/i);
const jobId = jobMatch ? jobMatch[1] : '';

// Get entire chat text (may contain URL before/after the name)
const raw = ($('When chat message received').item.json.chatInput || '').trim();

// Remove URLs so regex won't match inside them
const text = raw.replace(/https?:\/\/\S+/gi, ' ').replace(/\s+/g, ' ').trim();

// Try to find a title + name anywhere in the text
const re = /\b(mr|mrs|ms|miss|dr|prof)\.?\s+([A-Za-zÀ-ÖØ-öø-ÿ'’-]+(?:\s+[A-Za-zÀ-ÖØ-öø-ÿ'’-]+){0,6})\b/i;
const m = text.match(re);

let titleContact = '';
let fullName = '';

if (m) {
  const normTitle = m[1].toLowerCase();
  const titleMap = { mr: 'Mr.', mrs: 'Mrs.', ms: 'Ms.', miss: 'Ms.', dr: 'Dr.', prof: 'Prof.' };
  titleContact = titleMap[normTitle] || (m[1][0].toUpperCase() + m[1].slice(1) + '.');
  fullName = m[2].replace(/\s+/g, ' ').trim();
} else {
  // Fallback: pick the first non-URL non-empty line and treat it as a name
  const nameLine = raw
    .split(/\r?\n/)
    .map(s => s.trim())
    .filter(s => s && !/^https?:\/\//i.test(s))[0] || '';
  fullName = nameLine.replace(/\b(mr|mrs|ms|miss|dr|prof)\.?\b/i, '').replace(/\s+/g, ' ').trim();
}

// Split into name & surname (last token = surname)
let contactName = '';
let contactSurname = '';
if (fullName) {
  const parts = fullName.split(' ');
  contactSurname = parts.pop();
  contactName = parts.join(' ');
}

return [{
  json: {
    titleContact,        // e.g., "Mr."
    contactName,         // e.g., "Mirveys"
    contactSurname,      // e.g., "Halim"
    jobId                // LinkedIn job id for the Apify call
  }
}];

