const raw = $input.item.json;

function extractText(j) {
  if (typeof j.content === 'string') return j.content;
  if (Array.isArray(j.content)) {
    const block = j.content.find(b => b && b.type === 'text' && typeof b.text === 'string');
    if (block) return block.text;
  }
  if (typeof j.text === 'string') return j.text;
  if (typeof j.mergedResponse === 'string') return j.mergedResponse;
  if (typeof j.output === 'string') return j.output;
  throw new Error('Could not find text in Claude response. Keys: ' + Object.keys(j).join(', '));
}

let text = extractText(raw).trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Claude output was not valid JSON: ' + e.message + '\n---\n' + text.slice(0, 500));
}

return [{ json: { message: { content: parsed } } }];

// Builds short, readable file-name parts from the job title and company, e.g. DataAnalyst + Acme
function shortLabel(text, maxWords) {
  if (!text) return '';
  let t = String(text);
  t = t.replace(/\([^)]*\)/g, '').replace(/\[[^\]]*\]/g, '');
  t = t.split(/\s[-–—]\s|,|\s\/\s| and | or | with | for /i)[0];
  const legalSuffix = /^(gmbh|inc|ltd|llc|ag|co|corp|corporation|plc|s\.a\.|sa|se|kg|group|holding|holdings)$/i;
  const stop = new Set(['the', 'a', 'an', 'of', 'and', 'or', 'to', 'in', 'at', 'for']);
  const words = t.trim().split(/\s+/).filter(w => w && !stop.has(w.toLowerCase()) && !legalSuffix.test(w.replace(/\.$/, '')));
  return words.slice(0, maxWords)
    .map(w => w.replace(/[^A-Za-z0-9]/g, ''))
    .filter(Boolean)
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join('');
}

const jobTitle = $('Update sheet with Job').item.json.title;
const company = $('Update sheet with Job').item.json.name;

return [{ json: { short_title: shortLabel(jobTitle, 3) || 'Role', short_company: shortLabel(company, 2) || 'Company' } }];

/* Replace data CV (final) -- builds the CV document dynamically from the AI JSON.
   Bold markdown -> real bold, real hyperlinks, justified text, indented entry content,
   hard caps to keep the CV on one page. */

const safe = v => (v == null ? '' : String(v));
function parseMaybe(x){ if (typeof x === 'string'){ try{ return JSON.parse(x);}catch{} } return x; }

function allItems(nodeName){
  const runs = $items(nodeName) || [];
  if (Array.isArray(runs) && runs.length) return runs.flat();
  const one = $items(nodeName, 0, 0) || $items(nodeName, 0);
  return one ? [one] : [];
}

function looksLikeResume(obj){
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return false;
  const keys = Object.keys(obj);
  return keys.includes('summary') || keys.includes('experience') || keys.includes('skills') || keys.includes('education');
}
function findResume(root, depth=0){
  if (depth > 6 || root == null) return undefined;
  const v = parseMaybe(root);
  if (looksLikeResume(v)) return v;
  if (Array.isArray(v)){
    for (const el of v){ const found = findResume(el, depth+1); if (found) return found; }
    return undefined;
  }
  if (typeof v === 'object'){
    const hot = v?.message?.content ?? v?.content ?? v?.output ?? v?.data?.message?.content ?? v?.data?.content;
    const hotFound = findResume(hot, depth+1);
    if (hotFound) return hotFound;
    for (const key of Object.keys(v)){ const found = findResume(v[key], depth+1); if (found) return found; }
  }
  return undefined;
}

function readAI(){
  const items = allItems('Rewrite Resume');
  if (!items.length) throw new Error('Cannot read output of Rewrite Resume. Check node name and connection.');
  for (const it of items){
    const root = it?.json ?? it;
    const resume = findResume(root);
    if (resume) return resume;
  }
  throw new Error('Could not locate resume JSON in Rewrite Resume (tried summary/experience/skills/education).');
}

function readDocId(){
  const items = allItems('Copy CV template');
  for (const it of items){
    const id = it?.json?.id ?? it?.json?.data?.id ?? it?.json?.body?.id;
    if (id) return id;
  }
  throw new Error('Missing docId from Copy CV template (.json.id).');
}

const ai    = readAI();
const docId = readDocId();
const cfg   = $('Config').item.json;

/* Hard caps -- keep the CV on one page regardless of what the AI returns */
const MAX_BULLETS_PER_ROLE = 4;
const MAX_BULLETS_PER_PROJECT = 2;
const MAX_ROLES = 3;
const MAX_PROJECTS = 2;
const MAX_EDU = 3;

const BLUE = { red: 0.09, green: 0.24, blue: 0.49 };
const GRAY = { red: 0.42, green: 0.42, blue: 0.42 };

let content = '';
const styleReqs = [];
const bulletReqs = [];
const linkReqs = [];
const paraReqs = [];

const INDENT = { magnitude: 18, unit: 'PT' };

function setPara(range, { indentStart, alignment } = {}){
  const paragraphStyle = {};
  const fields = [];
  if (indentStart !== undefined){ paragraphStyle.indentStart = indentStart; fields.push('indentStart'); }
  if (alignment){ paragraphStyle.alignment = alignment; fields.push('alignment'); }
  if (!fields.length) return;
  paraReqs.push({ updateParagraphStyle: { range: { startIndex: range.start, endIndex: range.end }, paragraphStyle, fields: fields.join(',') } });
}

function push(text, opts = {}){
  const start = 1 + content.length;
  content += text;
  const end = 1 + content.length;
  if (opts.style){
    styleReqs.push({ updateTextStyle: { range: { startIndex: start, endIndex: end }, textStyle: opts.style, fields: opts.fields } });
  }
  if (opts.bullet){
    bulletReqs.push({ createParagraphBullets: { range: { startIndex: start, endIndex: end }, bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE' } });
  }
  if (opts.link){
    linkReqs.push({ updateTextStyle: { range: { startIndex: start, endIndex: end }, textStyle: { link: { url: opts.link } }, fields: 'link' } });
  }
  return { start, end };
}
function nl(n = 1){ content += '\n'.repeat(n); }

/* Strip markdown **bold** markers and apply real bold formatting to those spans */
function pushRich(text, opts = {}){
  const re = /\*\*(.+?)\*\*/g;
  let clean = '';
  const boldSpans = [];
  let lastIndex = 0;
  let m;
  while ((m = re.exec(text)) !== null){
    clean += text.slice(lastIndex, m.index);
    const boldStart = clean.length;
    clean += m[1];
    boldSpans.push([boldStart, clean.length]);
    lastIndex = re.lastIndex;
  }
  clean += text.slice(lastIndex);

  const range = push(clean, opts);
  boldSpans.forEach(([s, e]) => {
    styleReqs.push({
      updateTextStyle: {
        range: { startIndex: range.start + s, endIndex: range.start + e },
        textStyle: { bold: true },
        fields: 'bold'
      }
    });
  });
  return range;
}

const STYLE = {
  name:    { style: { bold: true, fontSize: { magnitude: 20, unit: 'PT' }, foregroundColor: { color: { rgbColor: BLUE } } }, fields: 'bold,fontSize,foregroundColor' },
  contact: { style: { fontSize: { magnitude: 9.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: GRAY } } }, fields: 'fontSize,foregroundColor' },
  contactLink: { style: { fontSize: { magnitude: 9.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: BLUE } }, underline: true }, fields: 'fontSize,foregroundColor,underline' },
  title:   { style: { bold: true, fontSize: { magnitude: 12, unit: 'PT' }, foregroundColor: { color: { rgbColor: BLUE } } }, fields: 'bold,fontSize,foregroundColor' },
  header:  { style: { bold: true, fontSize: { magnitude: 12.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: BLUE } } }, fields: 'bold,fontSize,foregroundColor' },
  body:    { style: { fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'fontSize' },
  bold11:  { style: { bold: true, fontSize: { magnitude: 11, unit: 'PT' } }, fields: 'bold,fontSize' },
  dateRow: { style: { italic: true, fontSize: { magnitude: 9.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: GRAY } } }, fields: 'italic,fontSize,foregroundColor' },
  label:   { style: { bold: true, fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'bold,fontSize' },
};

function sectionHeader(title){
  push(title.toUpperCase(), STYLE.header);
  nl();
}

/* --- Name --- */
push(`${cfg.applicant_name} ${cfg.applicant_surname}`, STYLE.name);
nl();

/* --- Contact line, with real hyperlinks on LinkedIn/Portfolio --- */
const contactStart = 1 + content.length;
push(`${cfg.applicant_location}   |   ${cfg.applicant_phone}   |   ${cfg.applicant_email}   |   `, STYLE.contact);
push('LinkedIn', { ...STYLE.contactLink, link: cfg.applicant_linkedin });
push('   |   ', STYLE.contact);
push('Portfolio', { ...STYLE.contactLink, link: cfg.applicant_portfolio });
const contactEnd = 1 + content.length;
nl();

push(cfg.applicant_title, STYLE.title);
nl();

/* --- Summary --- */
if (ai.summary){
  sectionHeader('Professional Summary');
  const r = pushRich(ai.summary, STYLE.body);
  setPara(r, { alignment: 'JUSTIFIED' });
  nl();
}

/* --- Experience --- */
const exps = (Array.isArray(ai.experience) ? ai.experience.filter(e => e && (e.title || e.company)) : []).slice(0, MAX_ROLES);
if (exps.length){
  sectionHeader('Professional Experience');
  exps.forEach((e) => {
    push([e.title, e.company].filter(Boolean).join(' | '), STYLE.bold11);
    nl();
    const dateLine = [e.dates, e.location].filter(Boolean).join(' | ');
    if (dateLine){
      const r = push(dateLine, STYLE.dateRow);
      setPara(r, { indentStart: INDENT });
      nl();
    }
    (Array.isArray(e.bullets) ? e.bullets.filter(Boolean) : []).slice(0, MAX_BULLETS_PER_ROLE).forEach(b => {
      const r = pushRich(b, { ...STYLE.body, bullet: true });
      setPara(r, { indentStart: INDENT, alignment: 'JUSTIFIED' });
      nl();
    });
  });
}

/* --- Projects --- */
const projs = (Array.isArray(ai.projects) ? ai.projects.filter(p => p && p.title) : []).slice(0, MAX_PROJECTS);
if (projs.length){
  sectionHeader('Projects');
  projs.forEach((p) => {
    push(p.title, STYLE.bold11);
    nl();
    (Array.isArray(p.bullets) ? p.bullets.filter(Boolean) : []).slice(0, MAX_BULLETS_PER_PROJECT).forEach(b => {
      const r = pushRich(b, { ...STYLE.body, bullet: true });
      setPara(r, { indentStart: INDENT, alignment: 'JUSTIFIED' });
      nl();
    });
  });
}

/* --- Education --- */
const edus = (Array.isArray(ai.education) ? ai.education.filter(e => e && (e.degree || e.institution)) : []).slice(0, MAX_EDU);
if (edus.length){
  sectionHeader('Education');
  edus.forEach((ed) => {
    push([ed.degree, ed.institution].filter(Boolean).join(' | '), STYLE.bold11);
    nl();
    if (ed.detail){
      const r = pushRich(ed.detail, STYLE.body);
      setPara(r, { indentStart: INDENT, alignment: 'JUSTIFIED' });
      nl();
    }
  });
}

/* --- Skills & Languages --- */
const skills = ai.skills || {};
const skillLines = [];
if (skills.technical_stack) skillLines.push(['Technical: ', skills.technical_stack]);
if (skills.domain_expertise) skillLines.push(['Expertise: ', skills.domain_expertise]);
if (skills.languages) skillLines.push(['Languages: ', skills.languages]);
