    const labelRange = push(label, STYLE.label);
    const valueRange = pushRich(value, STYLE.body);
    setPara({ start: labelRange.start, end: valueRange.end }, { alignment: 'JUSTIFIED' });
    if (idx < skillLines.length - 1) nl();
  });
