    { range: `${tab}!A${n}:E${n}`, values: [vals.slice(0, 5)] },
    { range: `${tab}!G${n}:I${n}`, values: [vals.slice(6, 9)] },
    { range: `${tab}!M${n}:AL${n}`, values: [vals.slice(12, 38)] }
  ] };
} else {
  url = `${base}/${encodeURIComponent(tab)}!A:AL:append?valueInputOption=RAW&insertDataOption=INSERT_ROWS`;
  body = { values: [vals] };
}

row.id = String(row.id);
return [{ json: { url, body, row } }];

// Locates this job's row in the tracker and prepares the email + cover letter cells (columns K:L)
const cfg = $('Config').item.json;
const id = String($('Update sheet with Job').item.json.id);
const ids = (($input.item.json.values) || []).map(r => String((r || [])[0] ?? ''));
const n = ids.indexOf(id) + 1;
if (!n) throw new Error('Job id ' + id + ' not found in the tracker sheet');
const s = v => v == null ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
const tab = cfg.sheet_name || 'Jobs';
return [{ json: {
  url: `https://sheets.googleapis.com/v4/spreadsheets/${cfg.Job_list}/values/${encodeURIComponent(tab)}!K${n}:L${n}?valueInputOption=RAW`,
  body: { values: [[ s($('Add Email').item.json.message.content.emailContent), s($('Create Cover Letter').item.json.message.content) ]] }
} }];
